dtsPropsFor.StatCard:
label: string;
value: string;
sub?: string;
/** Tailwind text-color class for the value: "text-forest-600" for good news, "text-coral-700" for over-budget or negative. */
accent?: string;
icon?: React.ReactNode;
/** When set, the card becomes a button (e.g. to drill into its transactions). */
onClick?: () => void;

dtsPropsFor.EmptyState:
icon?: React.ReactNode;
/** Art shown as it is above the title, in place of the icon tile (e.g. <Omer pose="wave" size={112} />, only on screens where he belongs). */
illustration?: React.ReactNode;
title: string;
message: string;
children?: React.ReactNode;

dtsPropsFor.SortHeader:
/** The column this header sorts. */
sortKey: string;
label: string;
/** The currently active sort column. */
current: string;
asc: boolean;
onToggle: (key: string) => void;
/** 'right' puts the arrow left of the label so a right-aligned column stays flush. */
align?: 'left' | 'right';
/** false renders static text at the same width, so the header never jumps when sortability changes. */
sortable?: boolean;

dtsPropsFor.CategoryDonut:
/** Spending grouped by category, sorted high to low. */
data: { category: string; total: number; count: number }[];
/** Total spending shown in the donut center. */
total: number;
onSelect?: (category: string) => void;

dtsPropsFor.MonthlyTrend:
/** Per-month spending/income/net, oldest month first. */
data: { monthKey: string; spending: number; income: number; net: number }[];
/** Called with the "YYYY-MM" key when the user clicks a month's bars. */
onSelectMonth?: (monthKey: string) => void;

dtsPropsFor.TopMerchantsCard:
/** Transactions to rank merchants from (signed amounts; negative = spend). */
transactions: { id: string; date: string; description: string; amount: number; category: string }[];
/** Open the charges behind a merchant. */
onOpenGroup?: (ids: string[]) => void;
/** Open the full merchant list (shows the "View all" links when set). */
onViewAll?: () => void;
/** How many spending habits the full list holds, for the footer link. */
habitCount?: number;

dtsPropsFor.Omer:
/** What he's doing. Also what he does below 64px, where outfits don't show. */
pose?: 'idle' | 'wave' | 'cheer' | 'jump' | 'thinking' | 'oops' | 'proud' | 'giving';
/** A costume for one kind of moment, drawn in its own pose (it replaces `pose`). Shows only at 64px and up. */
outfit?: 'hero' | 'detective' | 'coach' | 'chef' | 'wrangler' | 'builder' | 'gardener' | 'graduate' | 'dreamer';
/** Width and height in px (default 120). */
size?: number;
/** Default suits the pose: 'breathe' at rest, 'hop' for cheer/jump, 'wobble' for oops. 'none' only pops in; 'still' doesn't move (use it in static mockups). */
motion?: 'breathe' | 'hop' | 'wobble' | 'none' | 'still';
/** Alt text when he carries meaning; omit when he's decoration. */
label?: string;
className?: string;
